def file_chip_icon_name(path):
    ext = os.path.splitext(str(path or ""))[1].lower()
    if ext in DELIVERABLE_EXTENSIONS:
        return DELIVERABLE_EXTENSIONS[ext][2]
    if ext in {".txt", ".log", ".json", ".csv", ".tsv", ".xml", ".yaml", ".yml"}:
        return "fa5s.file-alt"
    return "fa5s.file"

DELIVERABLE_SKIP_DIRS = {
    ".git",
    "__pycache__",
    ".pytest_cache",
    ".venv",
    "venv",
    "node_modules",
    "build",
    "dist",
}


def scan_workspace_deliverables(workspace_dir, limit=500):
    root = os.path.abspath(os.path.expanduser(str(workspace_dir or "").strip()))
    if not root or not os.path.isdir(root):
        return []
    items = []
    try:
        for dirpath, dirnames, filenames in os.walk(root):
            dirnames[:] = [
                name
                for name in dirnames
                if name not in DELIVERABLE_SKIP_DIRS and not name.startswith(".cache")
            ]
            for filename in filenames:
                ext = os.path.splitext(filename)[1].lower()
                if ext not in DELIVERABLE_EXTENSIONS:
                    continue
                path = os.path.join(dirpath, filename)
                try:
                    stat = os.stat(path)
                except OSError:
                    continue
                kind, label, icon = DELIVERABLE_EXTENSIONS[ext]
                try:
                    rel_path = os.path.relpath(path, root)
                except ValueError:
                    rel_path = path
                items.append(
                    {
                        "path": os.path.normpath(path),
                        "relative_path": os.path.normpath(rel_path),
                        "name": filename,
                        "kind": kind,
                        "type_label": label,
                        "icon": icon,
                        "size": stat.st_size,
                        "mtime": stat.st_mtime,
                    }
                )
                if len(items) >= int(limit or 500):
                    break
            if len(items) >= int(limit or 500):
                break
    except OSError:
        return []
    items.sort(key=lambda item: (item.get("mtime") or 0, item.get("relative_path") or ""), reverse=True)
    return items


def deliverable_preview_bootstrap_script():
    """Return the idempotent lightweight-preview policy injected before page scripts."""
    return r"""
(function () {
  if (window.__coworkLightPreviewInstalled) return;
  window.__coworkLightPreviewInstalled = true;
  const nativeRaf = window.requestAnimationFrame.bind(window);
  const nativeCancelRaf = window.cancelAnimationFrame.bind(window);
  const frameCallbacks = new Map();
  let nextFrameId = 1;
  let pumpId = 0;
  let lastFrame = 0;
  function pump(timestamp) {
    pumpId = 0;
    if (timestamp - lastFrame < 64) {
      pumpId = nativeRaf(pump);
      return;
    }
    lastFrame = timestamp;
    const callbacks = Array.from(frameCallbacks.values());
    frameCallbacks.clear();
    callbacks.forEach(function (callback) { callback(timestamp); });
    if (frameCallbacks.size) pumpId = nativeRaf(pump);
  }
  window.requestAnimationFrame = function (callback) {
    const id = nextFrameId++;
    frameCallbacks.set(id, callback);
    if (!pumpId) pumpId = nativeRaf(pump);
    return id;
  };
  window.cancelAnimationFrame = function (id) {
    frameCallbacks.delete(id);
    if (!frameCallbacks.size && pumpId) {
      nativeCancelRaf(pumpId);
      pumpId = 0;
    }
  };
  const nativeInterval = window.setInterval.bind(window);
  window.setInterval = function (callback, delay) {
    const args = Array.prototype.slice.call(arguments, 2);
    return nativeInterval.apply(window, [callback, Math.max(100, Number(delay) || 0)].concat(args));
  };
  function quietMedia(root) {
    if (!root || root.nodeType !== 1) return;
    const mediaItems = [];
    if (root.matches && root.matches('video,audio')) mediaItems.push(root);
    if (root.querySelectorAll) mediaItems.push.apply(mediaItems, root.querySelectorAll('video,audio'));
    mediaItems.forEach(function (media) {
      media.autoplay = false;
      try { media.pause(); } catch (_) {}
    });
  }
  function applyPolicy() {
    if (!document.documentElement) return;
    let style = document.getElementById('cowork-light-preview-style');
    if (!style) {
      style = document.createElement('style');
      style.id = 'cowork-light-preview-style';
      style.textContent = '*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}html{scrollbar-width:none!important}html::-webkit-scrollbar{display:none!important}';
      (document.head || document.documentElement).appendChild(style);
    }
    quietMedia(document.documentElement);
  }
  function canScrollInDirection(node, x, y) {
    if (!node) return false;
    const maxX = Math.max(0, node.scrollWidth - node.clientWidth);
    const maxY = Math.max(0, node.scrollHeight - node.clientHeight);
    const canX = x && maxX > 1 && ((x < 0 && node.scrollLeft > 0) || (x > 0 && node.scrollLeft < maxX));
    const canY = y && maxY > 1 && ((y < 0 && node.scrollTop > 0) || (y > 0 && node.scrollTop < maxY));
    return Boolean(canX || canY);
  }
  function findScrollTarget(start, x, y) {
    const pageScroller = document.scrollingElement || document.documentElement;
    let node = start && start.nodeType === 1 ? start : null;
    while (node && node !== document.documentElement) {
      const style = window.getComputedStyle(node);
      const scrollableX = /(auto|scroll|overlay)/.test(style.overflowX || '');
      const scrollableY = /(auto|scroll|overlay)/.test(style.overflowY || '');
      if (((x && scrollableX) || (y && scrollableY)) && canScrollInDirection(node, x, y)) return node;
      node = node.parentElement;
    }
    return canScrollInDirection(pageScroller, x, y) ? pageScroller : null;
  }
  window.__coworkScrollWheelAt = function (clientX, clientY, x, y) {
    const start = document.elementFromPoint(Number(clientX) || 0, Number(clientY) || 0);
    const target = findScrollTarget(start, Number(x) || 0, Number(y) || 0);
    if (!target) return '';
    const pageScroller = document.scrollingElement || document.documentElement;
    if (target === pageScroller) return 'page';
    target.scrollLeft += Number(x) || 0;
    target.scrollTop += Number(y) || 0;
    return 'nested';
  };
  window.__coworkPreviewMetrics = function () {
    const scroller = document.scrollingElement || document.documentElement;
    return {
      left: scroller.scrollLeft || 0,
      top: scroller.scrollTop || 0,
      width: scroller.scrollWidth || 0,
      height: scroller.scrollHeight || 0,
      clientWidth: scroller.clientWidth || 0,
      clientHeight: scroller.clientHeight || 0
    };
  };
  applyPolicy();
  document.addEventListener('DOMContentLoaded', applyPolicy, {once: true});
  new MutationObserver(function (mutations) {
    mutations.forEach(function (mutation) {
      mutation.addedNodes.forEach(quietMedia);
    });
  }).observe(document.documentElement || document, {childList: true, subtree: true});
})();
"""


def deliverable_preview_settle_script():
    return r"""
(function () {
  document.querySelectorAll('video,audio').forEach(function (media) {
    media.autoplay = false;
    try { media.pause(); } catch (_) {}
  });
  if (document.getAnimations) {
    document.getAnimations().forEach(function (animation) {
      try { animation.cancel(); } catch (_) {}
    });
  }
})();
"""


class DeliverableScanWorker(QThread):
    completed = Signal(object, int)
    failed = Signal(str, int)

    def __init__(self, workspace_dir, records, generation, parent=None):
        super().__init__(parent)
        self.workspace_dir = workspace_dir
        self.records = list(records or [])
        self.generation = int(generation)

    def run(self):
        try:
            items = []
            root = os.path.abspath(self.workspace_dir)
            for record in self.records:
                path = os.path.normpath(str(record.get("path") or ""))
                if not path or not os.path.isfile(path):
                    continue
                ext = os.path.splitext(path)[1].lower()
                if ext not in DELIVERABLE_EXTENSIONS:
                    continue
                stat = os.stat(path)
                kind, label, icon = DELIVERABLE_EXTENSIONS[ext]
                try:
                    relative_path = os.path.relpath(path, root)
                except ValueError:
                    relative_path = path
                items.append({
                    "path": path,
                    "relative_path": os.path.normpath(relative_path),
                    "name": os.path.basename(path),
                    "kind": kind,
                    "type_label": label,
                    "icon": icon,
                    "size": stat.st_size,
                    "mtime": stat.st_mtime,
                    "source": record.get("source") or "generated",
                    "conversation_id": record.get("conversation_id"),
                })
            items.sort(key=lambda item: (item.get("mtime") or 0, item.get("relative_path") or ""), reverse=True)
            self.completed.emit(items, self.generation)
        except Exception as exc:
            self.failed.emit(str(exc), self.generation)


class SkillManagerLoadWorker(QThread):
    completed = Signal(object)

    def __init__(self, config_manager, workspace_dir=None, load_mcp_tools=False, catalog_service=None, parent=None):
        super().__init__(parent)
        self.config_manager = config_manager
        self.workspace_dir = workspace_dir
        self.load_mcp_tools = bool(load_mcp_tools)
        self.catalog_service = catalog_service

    def run(self):
        try:
            if self.catalog_service is not None:
                snapshot = self.catalog_service.preload()
                manager = snapshot.manager
            else:
                manager = SkillManager(
                    self.workspace_dir,
                    self.config_manager,
                    auto_load=True,
                    load_mcp_tools=self.load_mcp_tools,
                    prepare_dependencies=False,
                )
            self.completed.emit({"ok": True, "skill_manager": manager})
        except Exception as exc:
            self.completed.emit({
                "ok": False,
                "error": str(exc),
                "traceback": traceback.format_exc(),
            })


class SkillCatalogRefreshWorker(QThread):
    completed = Signal(object)

    def __init__(self, client, skill_names, action, session_id, parent=None):
        super().__init__(parent)
        self.client = client
        self.skill_names = list(skill_names or [])
        self.action = str(action or "updated")
        self.session_id = str(session_id or "")

    def run(self):
        try:
            result = self.client.refresh_skills(
                self.skill_names,
                action=self.action,
                source="ui",
                session_id=self.session_id,
            )
            self.completed.emit(result or {"status": "error", "error": "Daemon 无响应"})
        except Exception as exc:
            self.completed.emit({"status": "error", "error": str(exc)})


class SkillDependencyRetryWorker(QThread):
    completed = Signal(str, object)

    def __init__(self, coordinator, skill_name, python_dependencies, node_dependencies, parent=None):
        super().__init__(parent)
        self.coordinator = coordinator
        self.skill_name = str(skill_name or "")
        self.python_dependencies = list(python_dependencies or [])
        self.node_dependencies = list(node_dependencies or [])

    def run(self):
        result = self.coordinator.ensure_ready(
            self.skill_name,
            python_dependencies=self.python_dependencies,
            node_dependencies=self.node_dependencies,
            retry=True,
        )
        self.completed.emit(self.skill_name, result)


def clarify_phase_label(phase):
    mapping = {
        CLARIFY_MODE_DISABLED: "未启用",
        CLARIFY_MODE_EXPLORING: "澄清中",
        CLARIFY_MODE_AWAITING_USER_INPUT: "等待输入",
    }
    return mapping.get(normalize_clarify_phase(phase), "未启用")


def readable_skill_name(skill):
    if not isinstance(skill, dict):
        return ""
    return skill.get("display_name") or skill.get("description_cn") or skill.get("name", "")


def readable_risk_level(value):
    text = (value or "").strip().lower()
    if text == "high":
        return ("高风险", DesignTokens.error_text)
    if text == "medium":
        return ("中风险", DesignTokens.warning_text)
    if text == "low":
        return ("低风险", DesignTokens.info_text)
    return ("常规", DesignTokens.text_secondary)


def summarize_skill_terms(values, max_items=3, max_chars=72):
    parts = [str(item).strip() for item in (values or []) if str(item).strip()]
    if not parts:
        return ""
    summary = "、".join(parts[:max_items])
    if len(parts) > max_items:
        summary += " 等"
    if len(summary) > max_chars:
        summary = summary[: max_chars - 1].rstrip("、，, ") + "…"
    return summary


def apple_checkable_list_style(radius=14, bg=None, padding=6):
    bg = bg or DesignTokens.bg_card
    checked_bg = rgba_from_hex(DesignTokens.primary, 0.12)
    checked_border = rgba_from_hex(DesignTokens.primary, 0.26)
    return (
        f"QListWidget {{ background: {bg}; border: 1px solid {DesignTokens.border}; "
        f"border-radius: {radius}px; padding: {padding}px; }}"
        f"QListWidget::item {{ padding: 10px 12px; border-radius: 10px; color: {DesignTokens.text_primary}; }}"
        f"QListWidget::item:selected {{ background: {DesignTokens.primary_soft}; color: {DesignTokens.text_primary}; }}"
        "QListWidget::indicator { width: 18px; height: 18px; }"
        f"QListWidget::indicator:unchecked {{ background: rgba(255, 255, 255, 0.96); border: 1px solid {DesignTokens.border_strong}; border-radius: 6px; }}"
        f"QListWidget::indicator:unchecked:hover {{ border-color: {DesignTokens.primary}; background: rgba(255, 255, 255, 1); }}"
        f"QListWidget::indicator:checked {{ background: {checked_bg}; border: 1px solid {checked_border}; border-radius: 6px; }}"
        f"QListWidget::indicator:checked:hover {{ background: {rgba_from_hex(DesignTokens.primary, 0.16)}; border-color: {DesignTokens.primary}; }}"
    )


class AppleCheckableListDelegate(QStyledItemDelegate):
    def __init__(self, parent=None, row_height=44):
        super().__init__(parent)
        self.row_height = int(row_height or 44)

    def sizeHint(self, option, index):
        size = super().sizeHint(option, index)
        size.setHeight(max(size.height(), self.row_height))
        return size

    def _alpha_color(self, color, alpha):
        result = QColor(color)
        result.setAlpha(int(alpha))
        return result

    def _check_state_value(self, value):
        return getattr(value, "value", value)

    def _is_checked(self, value):
        return self._check_state_value(value) == self._check_state_value(Qt.Checked)

    def paint(self, painter, option, index):
        painter.save()
        try:
            rect = option.rect.adjusted(6, 3, -6, -3)
            checked = self._is_checked(index.data(Qt.CheckStateRole))
            hovered = bool(option.state & QStyle.State_MouseOver)

            if checked:
                painter.setPen(Qt.NoPen)
                painter.setBrush(self._alpha_color(DesignTokens.primary, 22 if not hovered else 34))
                painter.drawRoundedRect(rect, 10, 10)
            elif hovered:
                painter.setPen(Qt.NoPen)
                painter.setBrush(self._alpha_color(DesignTokens.primary, 10))
                painter.drawRoundedRect(rect, 10, 10)

            box_size = 20
            box_rect = QRect(
                rect.left() + 12,
                rect.top() + max((rect.height() - box_size) // 2, 0),
                box_size,
                box_size,
            )
            painter.setRenderHint(QPainter.Antialiasing, True)
            if checked:
                painter.setPen(QPen(QColor(DesignTokens.primary), 1.2))
                painter.setBrush(QColor(DesignTokens.primary))
            else:
                painter.setPen(QPen(self._alpha_color(DesignTokens.text_tertiary, 160), 1.2))
                painter.setBrush(QColor(255, 255, 255, 245))
            painter.drawRoundedRect(box_rect, 6, 6)

            if checked:
                check_pen = QPen(QColor("white"), 2.2, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin)
                painter.setPen(check_pen)
                p1 = QPoint(box_rect.left() + 5, box_rect.center().y())
                p2 = QPoint(box_rect.left() + 9, box_rect.bottom() - 6)
                p3 = QPoint(box_rect.right() - 5, box_rect.top() + 6)
                painter.drawLine(p1, p2)
                painter.drawLine(p2, p3)

            text_rect = rect.adjusted(44, 0, -12, 0)
            text = str(index.data(Qt.DisplayRole) or "")
            metrics = QFontMetrics(option.font)
            elided = metrics.elidedText(text, Qt.ElideRight, max(text_rect.width(), 20))
            painter.setPen(QColor(DesignTokens.text_primary))
            painter.setFont(option.font)
            painter.drawText(text_rect, Qt.AlignVCenter | Qt.AlignLeft, elided)
        finally:
            painter.restore()

    def editorEvent(self, event, model, option, index):
        if not (index.flags() & Qt.ItemIsUserCheckable):
            return super().editorEvent(event, model, option, index)
        if event.type() == QEvent.MouseButtonRelease:
            if hasattr(event, "button") and event.button() != Qt.LeftButton:
                return False
            self._toggle(model, index)
            return True
        if event.type() == QEvent.KeyPress and event.key() in (Qt.Key_Space, Qt.Key_Return, Qt.Key_Enter):
            self._toggle(model, index)
            return True
        return super().editorEvent(event, model, option, index)

    def _toggle(self, model, index):
        current = index.data(Qt.CheckStateRole)
        next_state = Qt.Unchecked if self._is_checked(current) else Qt.Checked
        model.setData(index, next_state, Qt.CheckStateRole)


def apply_apple_checkable_list_behavior(list_widget, radius=14, bg=None, padding=6, row_height=44):
    list_widget.setStyleSheet(apple_list_style(border=True, bg=bg or DesignTokens.bg_card, radius=radius, padding=padding))
    list_widget.setItemDelegate(AppleCheckableListDelegate(list_widget, row_height=row_height))
    list_widget.setSelectionMode(QAbstractItemView.NoSelection)
    list_widget.setMouseTracking(True)
    list_widget.viewport().setMouseTracking(True)
    list_widget.setUniformItemSizes(False)
    list_widget.setAlternatingRowColors(False)
    return list_widget


def skill_center_tab_key(skill):
    if not isinstance(skill, dict):
        return "builtin"
    if str(skill.get("source_format") or "").strip() == SkillManager.MCP_SOURCE_FORMAT:
        return "mcp"
    if str(skill.get("source_type") or "").strip() == "bundled_plugin" or skill.get("type") == "bundled_plugin":
        return "optional"
    is_custom = skill.get("type") == "ai_generated" or skill.get("created_by") == "ai"
    return "custom" if is_custom else "builtin"


def skill_center_is_builtin(skill):
    return skill_center_tab_key(skill) == "builtin"


def skill_center_matches_filters(skill, query="", status_filter="all"):
    if not isinstance(skill, dict):
        return False
    enabled = bool(skill.get("enabled"))
    if status_filter == "enabled" and not enabled:
        return False
    if status_filter == "disabled" and enabled:
        return False
    normalized_query = str(query or "").strip().lower()
    if not normalized_query:
        return True
    haystack = " ".join(
        [
            str(skill.get("display_name") or ""),
            str(skill.get("name") or ""),
            str(skill.get("user_description") or ""),
            str(skill.get("description") or ""),
            " ".join(str(item) for item in (skill.get("tools") or [])),
            " ".join(str(item) for item in (skill.get("use_cases") or [])),
        ]
    ).lower()
    return normalized_query in haystack


SKILL_RUNTIME_RELOAD_PENDING_ATTR = "_skill_runtime_reload_pending"


def mark_skill_runtime_reload_pending(skill_manager, pending=True):
    if skill_manager is None:
        return
    setattr(skill_manager, SKILL_RUNTIME_RELOAD_PENDING_ATTR, bool(pending))


def skill_runtime_reload_pending(skill_manager):
    if skill_manager is None:
        return False
    return bool(getattr(skill_manager, "__dict__", {}).get(SKILL_RUNTIME_RELOAD_PENDING_ATTR, False))


def flush_pending_skill_runtime_reload(skill_manager):
    if not skill_runtime_reload_pending(skill_manager):
        return False
    skill_manager.load_skills()
    mark_skill_runtime_reload_pending(skill_manager, False)
    return True


def is_hidden_manual_skill_change_message(message):
    if not isinstance(message, dict):
        return False
    meta = message.get("meta") if isinstance(message.get("meta"), dict) else {}
    payload = meta.get("skill_change") if isinstance(meta.get("skill_change"), dict) else {}
    return (
        bool(meta.get("ui_only"))
        and str(payload.get("source") or "").strip().lower() == "ui"
        and str(payload.get("action") or "").strip().lower() in {"enabled", "disabled"}
    )


