class AppleSwitch(QCheckBox):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setFixedSize(52, 30)
        self.setCursor(Qt.PointingHandCursor)
        self.setText("")
        self.setFocusPolicy(Qt.StrongFocus)

    def hitButton(self, pos):
        return self.rect().contains(pos)

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)
        checked = self.isChecked()
        track = QRect(2, 3, 48, 24)
        is_enabled = self.isEnabled()
        if not is_enabled:
            track_color = QColor(rgba_from_hex(DesignTokens.text_tertiary, 0.24))
        else:
            track_color = QColor(DesignTokens.success_accent if checked else "#d1d5db")
        if self.underMouse() and not checked and is_enabled:
            track_color = QColor("#c4c9d3")
        border_color = QColor(rgba_from_hex(DesignTokens.text_tertiary, 0.42)) if not is_enabled else QColor(DesignTokens.success_accent if checked else "#c7ccd5")
        painter.setPen(QPen(border_color, 1))
        painter.setBrush(QBrush(track_color))
        painter.drawRoundedRect(track, 12, 12)

        knob_x = 27 if checked else 5
        knob = QRect(knob_x, 5, 20, 20)
        painter.setPen(Qt.NoPen)
        painter.setBrush(QColor("#ffffff" if is_enabled else "#f8f9fb"))
        painter.drawEllipse(knob)


class AppleSelectionCheck(QCheckBox):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setFixedSize(24, 24)
        self.setCursor(Qt.PointingHandCursor)
        self.setText("")

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)
        circle = QRect(3, 3, 18, 18)
        if self.isChecked():
            painter.setPen(QPen(QColor(DesignTokens.primary), 1))
            painter.setBrush(QBrush(QColor(DesignTokens.primary)))
            painter.drawEllipse(circle)
            painter.setPen(QPen(QColor("#ffffff"), 2, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
            painter.drawLine(8, 12, 11, 15)
            painter.drawLine(11, 15, 17, 9)
            return
        border = QColor(DesignTokens.primary if self.underMouse() else DesignTokens.border_strong)
        painter.setPen(QPen(border, 1.5))
        painter.setBrush(QBrush(QColor("#ffffff")))
        painter.drawEllipse(circle)


class CapabilityWorkbenchDialog(QDialog):
    def __init__(self, skill, skill_manager, config_manager, parent=None):
        super().__init__(parent)
        self.skill = dict(skill or {})
        self.skill_manager = skill_manager
        self.config_manager = config_manager
        self.skill_name = str(self.skill.get("name") or "").strip()
        self.current_file_path = ""
        self.tool_worker = None
        self.mcp_worker = None
        self.mcp_tools = []
        self.managed_mcp_server = None
        self.config_editors = {}
        self.setWindowTitle("能力工作台")
        self.resize(980, 680)
        apply_product_dialog(self, "CapabilityWorkbenchDialog")

        layout = QVBoxLayout(self)
        layout.setContentsMargins(22, 20, 22, 20)
        layout.setSpacing(14)

        header = QHBoxLayout()
        title_box = QVBoxLayout()
        title_box.setSpacing(4)
        title = QLabel(self.skill.get("display_name") or self.skill_name or "能力工作台")
        title.setProperty("roleTitle", True)
        subtitle = QLabel(self._subtitle_text())
        subtitle.setProperty("roleSubtitle", True)
        subtitle.setWordWrap(True)
        title_box.addWidget(title)
        title_box.addWidget(subtitle)
        header.addLayout(title_box, 1)
        close_btn = QPushButton("关闭")
        close_btn.setStyleSheet(apple_button_style("secondary", radius=14))
        close_btn.clicked.connect(self.accept)
        header.addWidget(close_btn)
        layout.addLayout(header)

        self.tabs = QTabWidget()
        layout.addWidget(self.tabs, 1)
        if self._is_mcp_skill():
            self._build_mcp_tabs()
        else:
            self._build_skill_tabs()

    def _subtitle_text(self):
        if self._is_mcp_skill():
            return "调试 MCP 连接、查看 tools，并用 JSON 参数直接调用 tool。"
        if self.skill_manager.is_skill_editable(self.skill_name):
            return "编辑用户能力文件、验证结构，并直接调试该能力暴露的工具或脚本。"
        return "内置能力为只读模式，可查看文件并调试已暴露工具。"

    def _is_mcp_skill(self):
        return str(self.skill.get("source_format") or "") == SkillManager.MCP_SOURCE_FORMAT

    def _format_payload(self, value):
        if isinstance(value, str):
            try:
                parsed = json.loads(value)
                return json.dumps(parsed, ensure_ascii=False, indent=2)
            except Exception:
                return value
        try:
            return json.dumps(value, ensure_ascii=False, indent=2)
        except Exception:
            return str(value)

    def _parse_json_editor(self, editor, fallback):
        raw = editor.toPlainText().strip()
        if not raw:
            return fallback
        try:
            return json.loads(raw)
        except Exception as exc:
            QMessageBox.warning(self, "JSON 参数", f"JSON 格式无效：{exc}")
            return None

    def _build_skill_tabs(self):
        self._build_config_tab()
        self._build_files_tab()
        self._build_tool_debug_tab()
        self._build_script_debug_tab()

    def _skill_config_fields(self):
        fields = self.skill.get("config_fields") or []
        if fields:
            return fields
        if hasattr(self.skill_manager, "get_skill_config_fields"):
            return self.skill_manager.get_skill_config_fields(self.skill_name)
        return []

    def _skill_mcp_server_presets(self):
        presets = self.skill.get("mcp_server_presets") or []
        if presets:
            return presets
        if hasattr(self.skill_manager, "get_skill_mcp_server_presets"):
            return self.skill_manager.get_skill_mcp_server_presets(self.skill_name)
        return []

    def _build_config_tab(self):
        fields = [field for field in self._skill_config_fields() if isinstance(field, dict)]
        if not fields:
            return
        page = QWidget()
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 8, 0, 0)
        layout.setSpacing(12)

        hint = QLabel("这些配置会在运行该能力的脚本或工具时提供给它。必填项缺失时会直接报错。")
        hint.setWordWrap(True)
        hint.setStyleSheet(apple_settings_inline_note_style())
        layout.addWidget(hint)

        card, card_layout = build_settings_surface("运行配置", "保存后下次调试或调用该能力时生效。", radius=18)
        form = QFormLayout()
        form.setSpacing(12)
        configure_responsive_form_layout(form)
        values = self.config_manager.get_skill_config(self.skill_name) if hasattr(self.config_manager, "get_skill_config") else {}
        self.config_editors = {}
        for field in fields:
            name = str(field.get("name") or "").strip()
            if not name:
                continue
            current_value = str(values.get(name, "") or field.get("default") or "")
            kind = str(field.get("kind") or "text").lower()
            if kind == "select":
                editor = QComboBox()
                for option in field.get("options") or []:
                    if not isinstance(option, dict):
                        continue
                    option_value = str(option.get("value") or "").strip()
                    if option_value:
                        editor.addItem(str(option.get("label") or option_value), option_value)
                selected_index = editor.findData(current_value)
                if selected_index >= 0:
                    editor.setCurrentIndex(selected_index)
            else:
                editor = QLineEdit()
                editor.setText(current_value)
                editor.setPlaceholderText(str(field.get("placeholder") or ""))
                if kind == "secret":
                    editor.setEchoMode(QLineEdit.Password)
            editor.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            label = str(field.get("label") or name)
            if field.get("required"):
                label += " *"
            help_text = str(field.get("help") or "").strip()
            if help_text:
                editor.setToolTip(help_text)
            form.addRow(build_form_row_label(label), editor)
            self.config_editors[name] = editor
        card_layout.addLayout(form)
        layout.addWidget(card)

        self.config_status = QLabel("")
        self.config_status.setWordWrap(True)
        self.config_status.setStyleSheet(apple_settings_inline_note_style())
        layout.addWidget(self.config_status)

        row = QHBoxLayout()
        row.addStretch()
        save_btn = QPushButton("保存配置")
        save_btn.setStyleSheet(apple_button_style("primary", radius=14))
        save_btn.clicked.connect(self.save_skill_config)
        row.addWidget(save_btn)
        layout.addLayout(row)

        if self._skill_mcp_server_presets():
            mcp_card, mcp_layout = build_settings_surface(
                "MCP 连接",
                "保存配置后会自动启用对应 MCP。需要确认远端或本地运行状态时，再单独测试连接。",
                radius=18,
            )
            preset_names = [
                str(item.get("name") or item.get("id") or "").strip()
                for item in self._skill_mcp_server_presets()
                if isinstance(item, dict)
            ]
            preset_label = QLabel("托管服务：" + "、".join([name for name in preset_names if name]))
            preset_label.setWordWrap(True)
            preset_label.setStyleSheet(apple_settings_inline_note_style())
            mcp_layout.addWidget(preset_label)
            existing_server = self._configured_managed_mcp_server()
            if existing_server and existing_server.get("enabled", True):
                managed_status_text = "MCP 已启用，连接待测试。"
            elif existing_server:
                managed_status_text = "MCP 已随 Skill 停用。"
            else:
                managed_status_text = "保存配置后可测试连接。"
            self.managed_mcp_status = QLabel(managed_status_text)
            self.managed_mcp_status.setWordWrap(True)
            self.managed_mcp_status.setStyleSheet(apple_settings_inline_note_style())
            mcp_layout.addWidget(self.managed_mcp_status)
            preset_row = QHBoxLayout()
            preset_row.addStretch()
            preset_btn = QPushButton("测试连接")
            preset_btn.setStyleSheet(apple_button_style("secondary", radius=14))
            preset_btn.clicked.connect(self.test_managed_mcp_connection)
            preset_row.addWidget(preset_btn)
            mcp_layout.addLayout(preset_row)
            layout.addWidget(mcp_card)
        layout.addStretch()
        self.tabs.addTab(page, "配置")
        self._refresh_config_status()

    def _refresh_config_status(self):
        label = getattr(self, "config_status", None)
        if label is None:
            return
        if not hasattr(self.skill_manager, "get_skill_config_status"):
            label.setText("")
            return
        status = self.skill_manager.get_skill_config_status(self.skill_name)
        missing = status.get("missing_required") or []
        if missing:
            label.setText("还缺少必填配置：" + "、".join(missing))
        elif status.get("config_errors"):
            label.setText("配置还不完整：" + "；".join(status.get("config_errors") or []))
        else:
            label.setText("配置完整。")

    def _current_skill_config_values(self):
        values = {}
        for name, editor in self.config_editors.items():
            if isinstance(editor, QComboBox):
                value = str(editor.currentData() or editor.currentText() or "").strip()
            else:
                value = editor.text().strip()
            if value:
                values[name] = value
        return values

    def _save_skill_config_values(self, show_message=True):
        if not hasattr(self.config_manager, "set_skill_config"):
            QMessageBox.warning(self, "能力配置", "当前配置管理器不支持能力配置。")
            return False
        values = self._current_skill_config_values()
        batch_save = getattr(self.config_manager, "batch_save", None)
        if callable(batch_save):
            with batch_save():
                self.config_manager.set_skill_config(self.skill_name, values)
                managed_result = self._materialize_managed_mcp_servers(publish_refresh=False)
        else:
            self.config_manager.set_skill_config(self.skill_name, values)
            managed_result = self._materialize_managed_mcp_servers(publish_refresh=False)
        if not managed_result.get("ok"):
            QMessageBox.warning(self, "MCP 配置", managed_result.get("error") or "无法启用 MCP。")
            self._refresh_config_status()
            return False
        if managed_result.get("servers") and not self._publish_managed_mcp_refresh():
            QMessageBox.warning(self, "MCP 配置", "MCP 配置已保存，但能力目录刷新失败。")
            self._refresh_config_status()
            return False
        self._refresh_config_status()
        if show_message:
            message = "配置已保存。"
            if managed_result.get("servers"):
                message = "配置已保存，MCP 已启用；可点击“测试连接”确认可用工具。"
            QMessageBox.information(self, "能力配置", message)
        return True

    def save_skill_config(self):
        self._save_skill_config_values(show_message=True)

    def _publish_managed_mcp_refresh(self):
        window = self.window()
        if hasattr(window, "publish_ui_skill_change"):
            published = bool(window.publish_ui_skill_change(self.skill_name, "updated", source="skill_config"))
            if published and hasattr(window, "skill_manager"):
                self.skill_manager = window.skill_manager
            return published
        self.skill_manager.load_skills(load_mcp_tools=False)
        return True

    def _materialize_managed_mcp_servers(self, publish_refresh=True):
        if not self._skill_mcp_server_presets():
            return {"ok": True, "error": "", "servers": []}
        if not hasattr(self.skill_manager, "build_skill_mcp_server_configs"):
            return {"ok": False, "error": "当前能力管理器不支持生成 MCP 配置。", "servers": []}
        result = self.skill_manager.build_skill_mcp_server_configs(self.skill_name)
        if not result.get("ok"):
            return result
        generated = result.get("servers") or []
        if not generated:
            return {"ok": False, "error": "没有可生成的 MCP 配置。", "servers": []}
        if hasattr(self.config_manager, "upsert_mcp_servers"):
            self.config_manager.upsert_mcp_servers(generated)
        else:
            servers = self.config_manager.get_mcp_servers() if hasattr(self.config_manager, "get_mcp_servers") else []
            by_id = {str(server.get("id") or "").strip(): index for index, server in enumerate(servers)}
            for server in generated:
                server_id = str(server.get("id") or "").strip()
                if server_id in by_id:
                    servers[by_id[server_id]] = server
                else:
                    servers.append(server)
            self.config_manager.set_mcp_servers(servers)
        self.managed_mcp_server = json.loads(json.dumps(generated[0], ensure_ascii=False))
        status = getattr(self, "managed_mcp_status", None)
        if status is not None:
            status.setText("MCP 已启用，连接待测试。")
        if publish_refresh and not self._publish_managed_mcp_refresh():
            return {"ok": False, "error": "MCP 配置已保存，但能力目录刷新失败。", "servers": generated}
        return {"ok": True, "error": "", "servers": generated}

    def _configured_managed_mcp_server(self):
        servers = self.config_manager.get_mcp_servers() if hasattr(self.config_manager, "get_mcp_servers") else []
        for server in servers:
            if str(server.get("source_skill") or "").strip() == self.skill_name:
                return server
        preset_ids = {
            str(item.get("id") or "").strip()
            for item in self._skill_mcp_server_presets()
            if isinstance(item, dict)
        }
        return next((server for server in servers if str(server.get("id") or "").strip() in preset_ids), None)

    def test_managed_mcp_connection(self):
        saved_values = self.config_manager.get_skill_config(self.skill_name) if hasattr(self.config_manager, "get_skill_config") else {}
        if self._current_skill_config_values() != saved_values:
            QMessageBox.warning(self, "测试连接", "当前配置尚未保存，请先保存配置再测试连接。")
            return
        server = self._configured_managed_mcp_server()
        if not server:
            QMessageBox.warning(self, "测试连接", "尚未生成托管 MCP，请先保存配置。")
            return
        if self.mcp_worker and self.mcp_worker.isRunning():
            return
        status = getattr(self, "managed_mcp_status", None)
        if status is not None:
            status.setText(f"正在测试 {server.get('name') or 'MCP'} ...")
        self.mcp_worker = McpConnectionWorker(server, config_manager=self.config_manager, parent=self)
        self.mcp_worker.finished_signal.connect(self._handle_managed_mcp_test_result)
        self.mcp_worker.finished.connect(self.mcp_worker.deleteLater)
        self.mcp_worker.start()

    def _handle_managed_mcp_test_result(self, result):
        self.mcp_worker = None
        status = getattr(self, "managed_mcp_status", None)
        if status is None:
            return
        if result.get("ok"):
            tools = result.get("tools") or []
            preview = "、".join(tools[:6]) if tools else "未暴露 tools"
            status.setText(f"连接可用，共发现 {result.get('tool_count', 0)} 个工具：{preview}")
            self._publish_managed_mcp_refresh()
            return
        status.setText("连接不可用：" + str(result.get("error") or "未知错误"))

    def _build_files_tab(self):
        page = QWidget()
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 8, 0, 0)
        layout.setSpacing(10)

        splitter = QSplitter(Qt.Horizontal)
        self.file_list = QListWidget()
        self.file_list.setStyleSheet(apple_list_style(border=False, bg=DesignTokens.bg_panel_strong, radius=14, padding=6))
        self.file_list.currentTextChanged.connect(self._load_selected_skill_file)
        splitter.addWidget(self.file_list)

        editor_wrap = QWidget()
        editor_layout = QVBoxLayout(editor_wrap)
        editor_layout.setContentsMargins(0, 0, 0, 0)
        editor_layout.setSpacing(8)
        self.file_status = QLabel("")
        self.file_status.setStyleSheet(apple_settings_inline_note_style())
        editor_layout.addWidget(self.file_status)
        self.file_editor = QTextEdit()
        self.file_editor.setStyleSheet(apple_code_edit_style(bg=DesignTokens.bg_panel_strong, radius=14, subtle=True, padding=10))
        editor_layout.addWidget(self.file_editor, 1)
        button_row = QHBoxLayout()
        self.validate_btn = QPushButton("验证")
        self.validate_btn.setStyleSheet(apple_button_style("secondary", radius=14))
        self.validate_btn.clicked.connect(self.validate_current_skill)
        self.save_file_btn = QPushButton("保存并重载")
        self.save_file_btn.setStyleSheet(apple_button_style("primary", radius=14))
        self.save_file_btn.clicked.connect(self.save_current_skill_file)
        self.save_file_btn.setVisible(self.skill_manager.is_skill_editable(self.skill_name))
        button_row.addStretch()
        button_row.addWidget(self.validate_btn)
        button_row.addWidget(self.save_file_btn)
        editor_layout.addLayout(button_row)
        splitter.addWidget(editor_wrap)
        splitter.setSizes([260, 720])
        layout.addWidget(splitter, 1)
        self.tabs.addTab(page, "文件")
        self.reload_skill_files()

    def reload_skill_files(self):
        payload = self.skill_manager.list_skill_files(self.skill_name)
        self.file_list.clear()
        if not payload.get("ok"):
            self.file_status.setText(payload.get("error") or "无法读取能力文件。")
            self.file_editor.setReadOnly(True)
            return
        for rel_path in payload.get("files") or []:
            self.file_list.addItem(rel_path)
        editable = bool(payload.get("editable"))
        self.file_editor.setReadOnly(not editable)
        self.file_status.setText("可编辑用户能力。" if editable else "只读：内置能力不能在这里修改。")
        if self.file_list.count():
            self.file_list.setCurrentRow(0)

    def _load_selected_skill_file(self, rel_path):
        self.current_file_path = str(rel_path or "").strip()
        if not self.current_file_path:
            return
        payload = self.skill_manager.read_skill_file(self.skill_name, self.current_file_path)
        if payload.get("ok"):
            self.file_editor.setPlainText(payload.get("content") or "")
            self.file_status.setText(self.current_file_path)
        else:
            self.file_editor.setPlainText("")
            self.file_status.setText(payload.get("error") or "读取失败。")

    def save_current_skill_file(self):
        if not self.current_file_path:
            return
        result = self.skill_manager.write_skill_file(
            self.skill_name,
            self.current_file_path,
            self.file_editor.toPlainText(),
        )
        if not result.get("ok"):
            QMessageBox.warning(self, "保存能力", result.get("error") or "保存失败。")
            return
        owner = self.parent()
        while owner is not None and not hasattr(owner, "publish_ui_skill_change"):
            owner = owner.parent() if hasattr(owner, "parent") else None
        if owner is None or not owner.publish_ui_skill_change(self.skill_name, "updated"):
            QMessageBox.warning(self, "保存能力", "文件已保存，但能力目录刷新失败。")
            return
        self.skill_manager = owner.skill_manager
        validation = result.get("validation") or {}
        if validation.get("ok", True):
            QMessageBox.information(self, "保存能力", "已保存并重新加载能力。")
        else:
            QMessageBox.warning(self, "保存能力", "已保存，但验证发现问题：\n" + "\n".join(validation.get("issues") or []))

    def validate_current_skill(self):
        result = self.skill_manager.validate_skill(self.skill_name)
        if result.get("ok"):
            QMessageBox.information(self, "验证能力", "验证通过。")
        else:
            QMessageBox.warning(self, "验证能力", "\n".join(result.get("issues") or ["验证失败。"]))

    def _build_tool_debug_tab(self):
        page = QWidget()
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 8, 0, 0)
        layout.setSpacing(10)
        self.tool_combo = QComboBox()
        for tool_name in self.skill.get("tools") or []:
            self.tool_combo.addItem(str(tool_name), str(tool_name))
        self.tool_combo.currentIndexChanged.connect(self._refresh_tool_schema)
        layout.addWidget(self.tool_combo)
        self.tool_schema = QTextEdit()
        self.tool_schema.setReadOnly(True)
        self.tool_schema.setFixedHeight(130)
        self.tool_schema.setStyleSheet(apple_code_edit_style(bg=DesignTokens.bg_panel_strong, radius=14, subtle=True, padding=10))
        layout.addWidget(self.tool_schema)
        self.tool_args = QTextEdit()
        self.tool_args.setPlaceholderText('{\n  "arg": "value"\n}')
        self.tool_args.setStyleSheet(apple_code_edit_style(bg=DesignTokens.bg_panel_strong, radius=14, subtle=True, padding=10))
        layout.addWidget(self.tool_args, 1)
        run_row = QHBoxLayout()
        run_row.addStretch()
        run_btn = QPushButton("运行 Tool")
        run_btn.setStyleSheet(apple_button_style("primary", radius=14))
        run_btn.clicked.connect(self.run_selected_tool)
        run_row.addWidget(run_btn)
        layout.addLayout(run_row)
        self.tool_result = QTextEdit()
        self.tool_result.setReadOnly(True)
        self.tool_result.setStyleSheet(apple_code_edit_style(bg=DesignTokens.bg_panel_strong, radius=14, subtle=True, padding=10))
        layout.addWidget(self.tool_result, 1)
        self.tabs.addTab(page, "Tool 调试")
        self._refresh_tool_schema()

    def _refresh_tool_schema(self):
        tool_name = str(self.tool_combo.currentData() or "")
        record = self.skill_manager.get_tool_record(tool_name) if tool_name else None
        if isinstance(record, dict):
            schema = record.get("parameters_schema") or {}
        else:
            schema = getattr(record, "parameters_schema", {}) if record else {}
        self.tool_schema.setPlainText(self._format_payload(schema))

    def _confirm_high_risk_debug(self):
        risk = str(self.skill.get("risk_level") or self.skill.get("security_level") or "").lower()
        if risk != "high":
            return True
        reply = QMessageBox.question(
            self,
            "调试高风险能力",
            "这个能力可能会访问或修改重要内容。确认要继续调试吗？",
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        return reply == QMessageBox.Yes

    def run_selected_tool(self):
        tool_name = str(self.tool_combo.currentData() or "")
        if not tool_name:
            QMessageBox.warning(self, "Tool 调试", "没有可调试的 tool。")
            return
        if not self._confirm_high_risk_debug():
            return
        args = self._parse_json_editor(self.tool_args, {})
        if args is None:
            return
        self.tool_result.setPlainText("Running...")
        self.tool_worker = SkillToolDebugWorker(self.skill_manager, tool_name, args, self)
        self.tool_worker.finished_signal.connect(self._handle_tool_result)
        self.tool_worker.finished.connect(self.tool_worker.deleteLater)
        self.tool_worker.start()

    def _handle_tool_result(self, result):
        self.tool_worker = None
        self.tool_result.setPlainText(self._format_payload(result.get("result") if result.get("ok") else result))

    def _build_script_debug_tab(self):
        page = QWidget()
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 8, 0, 0)
        layout.setSpacing(10)
        self.script_combo = QComboBox()
        for entry in self.skill.get("script_entries") or []:
            if isinstance(entry, dict):
                self.script_combo.addItem(str(entry.get("name") or entry.get("path") or "script"), dict(entry))
        layout.addWidget(self.script_combo)
        self.script_args = QTextEdit()
        self.script_args.setPlaceholderText('["--flag", "value"]')
        self.script_args.setStyleSheet(apple_code_edit_style(bg=DesignTokens.bg_panel_strong, radius=14, subtle=True, padding=10))
        layout.addWidget(self.script_args, 1)
        self.script_input = QTextEdit()
        self.script_input.setPlaceholderText("stdin 文本，可留空")
        self.script_input.setStyleSheet(apple_code_edit_style(bg=DesignTokens.bg_panel_strong, radius=14, subtle=True, padding=10))
        layout.addWidget(self.script_input, 1)
        row = QHBoxLayout()
        self.script_timeout = QSpinBox()
        self.script_timeout.setRange(5, 600)
        self.script_timeout.setValue(120)
        self.script_timeout.setSuffix(" 秒")
        row.addWidget(QLabel("Timeout"))
        row.addWidget(self.script_timeout)
        row.addStretch()
        run_btn = QPushButton("运行 Script")
        run_btn.setStyleSheet(apple_button_style("primary", radius=14))
        run_btn.clicked.connect(self.run_selected_script)
        row.addWidget(run_btn)
        layout.addLayout(row)
        self.script_result = QTextEdit()
        self.script_result.setReadOnly(True)
        self.script_result.setStyleSheet(apple_code_edit_style(bg=DesignTokens.bg_panel_strong, radius=14, subtle=True, padding=10))
        layout.addWidget(self.script_result, 1)
        self.tabs.addTab(page, "Script 调试")

    def run_selected_script(self):
        entry = self.script_combo.currentData()
        if not isinstance(entry, dict):
            QMessageBox.warning(self, "Script 调试", "没有声明 script_entries。")
            return
        if not self._confirm_high_risk_debug():
            return
        args = self._parse_json_editor(self.script_args, [])
        if args is None:
            return
        payload = {
            "skill_name": self.skill_name,
            "script_name": str(entry.get("name") or entry.get("path") or ""),
            "args": args,
            "input_text": self.script_input.toPlainText(),
            "timeout_seconds": int(self.script_timeout.value()),
        }
        self.script_result.setPlainText("Running...")
        self.tool_worker = SkillToolDebugWorker(self.skill_manager, "run_skill_script", payload, self)
        self.tool_worker.finished_signal.connect(self._handle_script_result)
        self.tool_worker.finished.connect(self.tool_worker.deleteLater)
        self.tool_worker.start()

    def _handle_script_result(self, result):
        self.tool_worker = None
        self.script_result.setPlainText(self._format_payload(result.get("result") if result.get("ok") else result))

    def _mcp_server_config(self):
        for server in self.config_manager.get_mcp_servers():
            skill_name = build_mcp_skill_name(server.get("id") or server.get("name") or "")
            if skill_name == self.skill_name:
                return json.loads(json.dumps(server, ensure_ascii=False))
        return {}

    def _build_mcp_tabs(self):
        page = QWidget()
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 8, 0, 0)
        layout.setSpacing(10)
        self.mcp_server = self._mcp_server_config()
        summary = QLabel(summarize_mcp_server(self.mcp_server) if self.mcp_server else "未找到 MCP 配置。")
        summary.setWordWrap(True)
        summary.setStyleSheet(apple_settings_inline_note_style())
        layout.addWidget(summary)
        row = QHBoxLayout()
        list_btn = QPushButton("连接并列出 Tools")
        list_btn.setStyleSheet(apple_button_style("secondary", radius=14))
        list_btn.clicked.connect(self.list_mcp_tools)
        edit_btn = QPushButton("编辑配置")
        edit_btn.setStyleSheet(apple_button_style("secondary", radius=14))
        edit_btn.clicked.connect(self.edit_mcp_config)
        row.addWidget(list_btn)
        row.addWidget(edit_btn)
        row.addStretch()
        layout.addLayout(row)
        self.mcp_tool_combo = QComboBox()
        layout.addWidget(self.mcp_tool_combo)
        self.mcp_args = QTextEdit()
        self.mcp_args.setPlaceholderText('{\n  "arg": "value"\n}')
        self.mcp_args.setStyleSheet(apple_code_edit_style(bg=DesignTokens.bg_panel_strong, radius=14, subtle=True, padding=10))
        layout.addWidget(self.mcp_args, 1)
        call_row = QHBoxLayout()
        call_row.addStretch()
        call_btn = QPushButton("调用 Tool")
        call_btn.setStyleSheet(apple_button_style("primary", radius=14))
        call_btn.clicked.connect(self.call_mcp_selected_tool)
        call_row.addWidget(call_btn)
        layout.addLayout(call_row)
        self.mcp_result = QTextEdit()
        self.mcp_result.setReadOnly(True)
        self.mcp_result.setStyleSheet(apple_code_edit_style(bg=DesignTokens.bg_panel_strong, radius=14, subtle=True, padding=10))
        layout.addWidget(self.mcp_result, 1)
        self.tabs.addTab(page, "MCP 调试")

    def list_mcp_tools(self):
        if not self.mcp_server:
            QMessageBox.warning(self, "MCP 调试", "未找到 MCP 配置。")
            return
        self.mcp_result.setPlainText("Connecting...")
        self.mcp_worker = McpToolDebugWorker("list", self.mcp_server, config_manager=self.config_manager, parent=self)
        self.mcp_worker.finished_signal.connect(self._handle_mcp_list_result)
        self.mcp_worker.finished.connect(self.mcp_worker.deleteLater)
        self.mcp_worker.start()

    def _handle_mcp_list_result(self, result):
        self.mcp_worker = None
        self.mcp_tool_combo.clear()
        if result.get("ok"):
            for tool in result.get("tools") or []:
                self.mcp_tool_combo.addItem(str(tool.get("name") or ""), tool)
        self.mcp_result.setPlainText(self._format_payload(result))

    def call_mcp_selected_tool(self):
        tool = self.mcp_tool_combo.currentData()
        tool_name = tool.get("name") if isinstance(tool, dict) else str(self.mcp_tool_combo.currentText() or "")
        if not tool_name:
            QMessageBox.warning(self, "MCP 调试", "请先列出并选择 tool。")
            return
        args = self._parse_json_editor(self.mcp_args, {})
        if args is None:
            return
        self.mcp_result.setPlainText("Calling...")
        self.mcp_worker = McpToolDebugWorker(
            "call", self.mcp_server, tool_name, args, config_manager=self.config_manager, parent=self
        )
        self.mcp_worker.finished_signal.connect(self._handle_mcp_call_result)
        self.mcp_worker.finished.connect(self.mcp_worker.deleteLater)
        self.mcp_worker.start()

    def _handle_mcp_call_result(self, result):
        self.mcp_worker = None
        self.mcp_result.setPlainText(self._format_payload(result))

    def edit_mcp_config(self):
        if not self.mcp_server:
            QMessageBox.warning(self, "MCP 调试", "未找到 MCP 配置。")
            return
        dialog = McpServerEditDialog(self.mcp_server, self)
        if dialog.exec() != QDialog.Accepted:
            return
        updated = dialog.get_server_config()
        servers = self.config_manager.get_mcp_servers()
        target_id = str(self.mcp_server.get("id") or "").strip()
        for index, server in enumerate(servers):
            if str(server.get("id") or "").strip() == target_id:
                servers[index] = updated
                break
        self.config_manager.set_mcp_servers(servers)
        self.skill_manager.load_skills()
        self.mcp_server = updated
        QMessageBox.information(self, "MCP 调试", "MCP 配置已保存并重新加载。")


class _LegacySkillsCenterDialog(QDialog):
    def __init__(self, skill_manager, config_manager, parent=None):
        super().__init__(parent)
        self.setWindowTitle("功能中心 (Skills Center)")
        self.resize(600, 500)
        self.skill_manager = skill_manager
        self.config_manager = config_manager
        
        layout = QVBoxLayout(self)
        
        # Tabs
        self.tabs = QTabWidget()
        layout.addWidget(self.tabs)
        
        # Tab 1: Standard Skills
        self.tab_standard = QWidget()
        self.layout_standard = QVBoxLayout(self.tab_standard)
        self.scroll_standard = QScrollArea()
        self.scroll_standard.setWidgetResizable(True)
        self.content_standard = QWidget()
        self.layout_content_standard = QVBoxLayout(self.content_standard)
        self.layout_content_standard.addStretch()
        self.scroll_standard.setWidget(self.content_standard)
        self.layout_standard.addWidget(self.scroll_standard)
        self.tabs.addTab(self.tab_standard, "已安装的功能模块")
        
        # Tab 2: AI Generated Skills
        self.tab_ai = QWidget()
        self.layout_ai = QVBoxLayout(self.tab_ai)
        self.scroll_ai = QScrollArea()
        self.scroll_ai.setWidgetResizable(True)
        self.content_ai = QWidget()
        self.layout_content_ai = QVBoxLayout(self.content_ai)
        self.layout_content_ai.addStretch()
        self.scroll_ai.setWidget(self.content_ai)
        self.layout_ai.addWidget(self.scroll_ai)
        self.tabs.addTab(self.tab_ai, "AI 生成的技能")
        
        # Bottom Bar (Import & Refresh)
        bottom_layout = QHBoxLayout()
        import_btn = QPushButton(" 导入新功能包")
        import_btn.setIcon(qta.icon('fa5s.box-open', color='#374151'))
        import_btn.clicked.connect(self.import_skill)
        bottom_layout.addWidget(import_btn)
        
        refresh_btn = QPushButton(" 刷新列表")
        refresh_btn.setIcon(qta.icon('fa5s.sync', color='#374151'))
        refresh_btn.clicked.connect(self.manual_refresh)
        bottom_layout.addWidget(refresh_btn)

        bottom_layout.addStretch()
        close_btn = QPushButton("关闭")
        close_btn.clicked.connect(self.accept)
        bottom_layout.addWidget(close_btn)
        layout.addLayout(bottom_layout)
        
        self.refresh_list()

    def manual_refresh(self):
        self.skill_manager.load_skills()
        self.refresh_list()
        QMessageBox.information(self, "刷新成功", "已重新扫描并加载所有技能模块。")

    def refresh_list(self):
        # Clear existing
        self._clear_layout(self.layout_content_standard)
        self._clear_layout(self.layout_content_ai)
        
        # Get skills
        skills = self.skill_manager.get_all_skills()
        for skill in skills:
            # Determine type
            is_ai = False
            if skill.get('type') == 'ai_generated' or skill.get('created_by') == 'ai':
                is_ai = True
            
            if is_ai:
                self.add_skill_card(skill, self.layout_content_ai)
            else:
                self.add_skill_card(skill, self.layout_content_standard)

    def _clear_layout(self, layout):
        while layout.count() > 1: # Keep stretch
            item = layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()

    def add_skill_card(self, skill, parent_layout):
        card = QFrame()
        card.setFrameStyle(QFrame.StyledPanel | QFrame.Raised)
        card.setStyleSheet("background-color: #f9f9f9; border-radius: 5px; margin-bottom: 5px;")
        
        h_layout = QHBoxLayout(card)
        
        # Info
        v_layout = QVBoxLayout()
        name_lbl = QLabel(f"{skill['name']}")
        name_lbl.setStyleSheet("font-weight: bold; font-size: 14px;")
        desc_lbl = QLabel(skill.get('description_cn') or skill.get('description', ''))
        desc_lbl.setWordWrap(True)
        desc_lbl.setStyleSheet("color: #555;")
        
        v_layout.addWidget(name_lbl)
        v_layout.addWidget(desc_lbl)

        # Dependencies
        deps = skill.get('dependencies', [])
        if deps and isinstance(deps, list):
            deps_str = ", ".join(deps)
            deps_lbl = QLabel(f" 依赖: {deps_str}")
            deps_lbl.setPixmap(qta.icon('fa5s.box', color='#1a73e8').pixmap(12, 12))
            deps_lbl = QLabel() # Re-create to use layout for icon+text or just text with emoji? 
            # Let's keep it simple with text but replace emoji with a small icon if possible or just text
            # Using simple text for now to avoid layout complexity in this list
            deps_lbl.setText(f"  依赖: {deps_str}")
            # Actually, let's use rich text to insert an icon or just use a simple char if qta is hard here
            # We can use a small pixmap label + text label in a horizontal layout
            
            deps_container = QWidget()
            deps_layout = QHBoxLayout(deps_container)
            deps_layout.setContentsMargins(0,0,0,0)
            deps_layout.setSpacing(4)
            
            icon_lbl = QLabel()
            icon_lbl.setPixmap(qta.icon('fa5s.box', color='#1a73e8').pixmap(12, 12))
            icon_lbl.setFixedSize(14, 14)
            
            txt_lbl = QLabel(f"依赖: {deps_str}")
            txt_lbl.setStyleSheet("color: #1a73e8; font-size: 11px;")
            
            deps_layout.addWidget(icon_lbl)
            deps_layout.addWidget(txt_lbl)
            deps_layout.addStretch()
            
            v_layout.addWidget(deps_container)

        # Experience (Evolution)
        exp = skill.get('experience', [])
        if exp and isinstance(exp, list):
             exp_frame = QFrame()
             exp_frame.setStyleSheet("background-color: #f1f8e9; border-radius: 4px; padding: 4px; margin-top: 4px;")
             exp_layout = QVBoxLayout(exp_frame)
             exp_layout.setContentsMargins(4,4,4,4)
             exp_layout.setSpacing(2)
             
             header_container = QWidget()
             h_layout_exp = QHBoxLayout(header_container)
             h_layout_exp.setContentsMargins(0,0,0,0)
             h_layout_exp.setSpacing(4)
             
             exp_icon = QLabel()
             exp_icon.setPixmap(qta.icon('fa5s.chart-line', color='#33691e').pixmap(12, 12))
             exp_header = QLabel(f"进化记录 ({len(exp)})")
             exp_header.setStyleSheet("font-weight: bold; color: #33691e; font-size: 11px;")
             
             h_layout_exp.addWidget(exp_icon)
             h_layout_exp.addWidget(exp_header)
             h_layout_exp.addStretch()
             
             exp_layout.addWidget(header_container)
             
             for e in exp:
                 e_lbl = QLabel(f"• {e}")
                 e_lbl.setStyleSheet("color: #558b2f; font-size: 10px;")
                 e_lbl.setWordWrap(True)
                 exp_layout.addWidget(e_lbl)
             v_layout.addWidget(exp_frame)

        # Security Level
        if 'security_level' in skill:
             sec_lvl = skill['security_level']
             color = "#e67c73" if "high" in sec_lvl.lower() else "#fbbc04"
             
             sec_container = QWidget()
             sec_layout = QHBoxLayout(sec_container)
             sec_layout.setContentsMargins(0,4,0,0)
             sec_layout.setSpacing(4)
             
             sec_icon = QLabel()
             sec_icon.setPixmap(qta.icon('fa5s.shield-alt', color=color).pixmap(12, 12))
             
             sec_lbl = QLabel(f"安全等级: {sec_lvl}")
             sec_lbl.setStyleSheet(f"color: {color}; font-size: 11px;")
             
             sec_layout.addWidget(sec_icon)
             sec_layout.addWidget(sec_lbl)
             sec_layout.addStretch()
             
             v_layout.addWidget(sec_container)

        h_layout.addLayout(v_layout, 1)
        h_layout.addStretch()
        
        # Controls
        controls_container = QWidget()
        controls_container.setFixedWidth(96)
        c_layout = QVBoxLayout(controls_container)
        c_layout.setContentsMargins(0, 0, 0, 0)
        c_layout.setAlignment(Qt.AlignRight | Qt.AlignVCenter)
        
        is_enabled = skill['enabled']
        toggle_btn = QPushButton("已启用" if is_enabled else "已禁用")
        toggle_btn.setFixedWidth(80)
        toggle_btn.setCursor(Qt.PointingHandCursor)
        
        if is_enabled:
             toggle_btn.setStyleSheet("""
                QPushButton { background-color: #e6f4ea; color: #137333; border: none; border-radius: 4px; font-weight: bold; padding: 6px; }
                QPushButton:hover { background-color: #ceead6; }
             """)
             toggle_btn.setToolTip("点击禁用")
        else:
             toggle_btn.setStyleSheet("""
                QPushButton { background-color: #f1f3f4; color: #5f6368; border: none; border-radius: 4px; font-weight: bold; padding: 6px; }
                QPushButton:hover { background-color: #e8eaed; }
             """)
             toggle_btn.setToolTip("点击启用")

        toggle_btn.clicked.connect(lambda: self.toggle_skill(skill['name'], not is_enabled))
        
        c_layout.addWidget(toggle_btn, 0, Qt.AlignRight | Qt.AlignVCenter)
        h_layout.addWidget(controls_container, 0, Qt.AlignRight | Qt.AlignVCenter)
        
        # Insert before stretch
        parent_layout.insertWidget(parent_layout.count()-1, card)

    def toggle_skill(self, name, enabled):
        self.config_manager.set_skill_enabled(name, enabled)
        self.refresh_list()

    def import_skill(self):
        path = QFileDialog.getExistingDirectory(self, "选择功能包目录 (包含 SKILL.md)")
        if path:
            success, msg = self.skill_manager.import_skill(path)
            if success:
                QMessageBox.information(self, "成功", msg)
                self.refresh_list()
            else:
                QMessageBox.warning(self, "失败", msg)

class ModelEditDialog(QDialog):
    def __init__(self, provider_id, model=None, parent=None):
        super().__init__(parent)
        self.setObjectName("ModelEditDialog")
        self.provider_id = provider_id
        model = dict(model or {})
        self._editing_existing = bool(model)
        self.setWindowTitle("编辑模型" if self._editing_existing else "添加模型")
        self.resize(560, 560)
        self.setMinimumSize(520, 520)
        self.setStyleSheet(linear_dialog_stylesheet("ModelEditDialog"))

        layout = QVBoxLayout(self)
        layout.setContentsMargins(22, 20, 22, 20)
        layout.setSpacing(16)

        header = QVBoxLayout()
        header.setSpacing(4)
        title = QLabel("编辑模型" if self._editing_existing else "添加模型")
        title.setProperty("roleTitle", True)
        subtitle = QLabel("显示名称用于界面选择；模型标识会原样发送给对应服务。")
        subtitle.setWordWrap(True)
        subtitle.setProperty("roleSubtitle", True)
        header.addWidget(title)
        header.addWidget(subtitle)
        layout.addLayout(header)

        card, card_layout = build_settings_surface("模型信息", "保持名称清晰，方便在提问栏和服务卡片里快速区分。", radius=18)
        form = QFormLayout()
        form.setSpacing(12)
        configure_responsive_form_layout(form)

        self.display_name_input = QLineEdit()
        self.display_name_input.setPlaceholderText("例如：DeepSeek V4 Pro")
        self.display_name_input.setText(str(model.get("display_name") or ""))
        form.addRow(build_form_row_label("显示名称"), self.display_name_input)

        self.model_name_input = QLineEdit()
        self.model_name_input.setPlaceholderText(DEFAULT_DEEPSEEK_MODEL if provider_id == "openai" else "claude-sonnet-4-5")
        self.model_name_input.setText(str(model.get("model_name") or ""))
        form.addRow(build_form_row_label("模型标识"), self.model_name_input)

        self.api_protocol_combo = None
        self._protocol_user_selected = False
        self._syncing_protocol = False
        if provider_id == "openai":
            self.api_protocol_combo = QComboBox()
            apply_settings_combo_style(self.api_protocol_combo)
            self.api_protocol_combo.addItem("Chat Completions", API_PROTOCOL_CHAT_COMPLETIONS)
            self.api_protocol_combo.addItem("Responses", API_PROTOCOL_RESPONSES)
            configured_protocol = normalize_openai_api_protocol(model.get("api_protocol"))
            protocol_index = self.api_protocol_combo.findData(configured_protocol)
            self.api_protocol_combo.setCurrentIndex(max(0, protocol_index))
            form.addRow(build_form_row_label("API 协议"), self.api_protocol_combo)

            def mark_protocol_selected(_index):
                if not self._syncing_protocol:
                    self._protocol_user_selected = True

            def sync_new_model_protocol(model_name):
                if self._editing_existing or self._protocol_user_selected:
                    return
                protocol = API_PROTOCOL_RESPONSES if is_gpt_5_6_model(model_name) else API_PROTOCOL_CHAT_COMPLETIONS
                index = self.api_protocol_combo.findData(protocol)
                self._syncing_protocol = True
                self.api_protocol_combo.setCurrentIndex(index)
                self._syncing_protocol = False

            self.api_protocol_combo.currentIndexChanged.connect(mark_protocol_selected)
            self.model_name_input.textChanged.connect(sync_new_model_protocol)
            sync_new_model_protocol(self.model_name_input.text())

        self.vision_check = QCheckBox("支持图片理解")
        self.vision_check.setChecked(bool(model.get("supports_vision", False)))
        form.addRow(build_form_row_label("图片理解"), self.vision_check)

        self.thinking_check = None
        self.reasoning_combo = None
        self.reasoning_checks = {}
        if provider_id == "openai":
            configured_efforts = normalize_reasoning_efforts(model.get("reasoning_efforts"))
            self.thinking_check = QCheckBox("支持推理强度")
            self.thinking_check.setChecked(bool(configured_efforts))
            form.addRow(build_form_row_label("推理"), self.thinking_check)

            effort_labels = {
                "none": "无",
                "low": "低",
                "medium": "中",
                "high": "高",
                "xhigh": "超高",
                "max": "极限",
            }
            effort_widget = QWidget()
            effort_layout = QHBoxLayout(effort_widget)
            effort_layout.setContentsMargins(0, 0, 0, 0)
            effort_layout.setSpacing(10)
            for effort in SUPPORTED_REASONING_EFFORTS:
                check = QCheckBox(effort_labels[effort])
                check.setChecked(effort in configured_efforts)
                self.reasoning_checks[effort] = check
                effort_layout.addWidget(check)
            effort_layout.addStretch()
            form.addRow(build_form_row_label("支持档位"), effort_widget)

            self.reasoning_combo = QComboBox()
            apply_settings_combo_style(self.reasoning_combo)
            for effort in SUPPORTED_REASONING_EFFORTS:
                self.reasoning_combo.addItem(effort_labels[effort], effort)
            effort = normalize_reasoning_effort(
                model.get("reasoning_effort", model.get("deepseek_reasoning_effort")),
                configured_efforts,
            )
            effort_index = self.reasoning_combo.findData(effort)
            if effort_index >= 0:
                self.reasoning_combo.setCurrentIndex(effort_index)
            form.addRow(build_form_row_label("初始档位"), self.reasoning_combo)

            def sync_reasoning_controls():
                enabled = self.thinking_check.isChecked()
                for check in self.reasoning_checks.values():
                    check.setEnabled(enabled)
                allowed = [key for key, check in self.reasoning_checks.items() if check.isChecked()]
                self.reasoning_combo.setEnabled(enabled and bool(allowed))
                for index in range(self.reasoning_combo.count()):
                    item_enabled = self.reasoning_combo.itemData(index) in allowed
                    self.reasoning_combo.model().item(index).setEnabled(item_enabled)
                if allowed and self.reasoning_combo.currentData() not in allowed:
                    self.reasoning_combo.setCurrentIndex(self.reasoning_combo.findData(allowed[0]))

            self.thinking_check.toggled.connect(lambda _checked: sync_reasoning_controls())
            for check in self.reasoning_checks.values():
                check.toggled.connect(lambda _checked: sync_reasoning_controls())
            sync_reasoning_controls()

        card_layout.addLayout(form)
        hint = QLabel("建议让显示名称包含服务来源或用途，例如“OpenRouter / Claude Sonnet”或“本地图像理解”。")
        hint.setWordWrap(True)
        hint.setStyleSheet(apple_settings_inline_note_style())
        card_layout.addWidget(hint)
        layout.addWidget(card)

        buttons = QHBoxLayout()
        buttons.addStretch()
        cancel_btn = QPushButton("取消")
        cancel_btn.setObjectName("SecondaryBtn")
        cancel_btn.clicked.connect(self.reject)
        ok_btn = QPushButton("保存")
        ok_btn.setObjectName("PrimaryBtn")
        ok_btn.clicked.connect(self.accept)
        buttons.addWidget(cancel_btn)
        buttons.addWidget(ok_btn)
        layout.addLayout(buttons)

    def get_model(self, existing_id=None):
        model_name = self.model_name_input.text().strip()
        display_name = self.display_name_input.text().strip() or model_name
        item = {
            "id": existing_id or "",
            "display_name": display_name,
            "model_name": model_name,
            "supports_vision": bool(self.vision_check and self.vision_check.isChecked()),
        }
        if self.provider_id == "openai":
            item["api_protocol"] = normalize_openai_api_protocol(
                self.api_protocol_combo.currentData() if self.api_protocol_combo else ""
            )
            enabled = bool(self.thinking_check and self.thinking_check.isChecked())
            efforts = [
                effort for effort, check in self.reasoning_checks.items()
                if enabled and check.isChecked()
            ]
            selected_effort = self.reasoning_combo.currentData() if efforts and self.reasoning_combo else ""
            item["deepseek_thinking_enabled"] = enabled
            item["deepseek_reasoning_effort"] = selected_effort or DEFAULT_DEEPSEEK_REASONING_EFFORT
            item["reasoning_efforts"] = efforts
            item["reasoning_effort"] = selected_effort
        return item

    def accept(self):
        if not self.model_name_input.text().strip():
            QMessageBox.warning(self, "模型配置", "请填写模型名称。")
            return
        if self.thinking_check and self.thinking_check.isChecked():
            if not any(check.isChecked() for check in self.reasoning_checks.values()):
                QMessageBox.warning(self, "模型配置", "请至少选择一个推理强度档位。")
                return
        super().accept()


class ModelConnectionTestWorker(QThread):
    finished_signal = Signal(dict)

    def __init__(self, profile, parent=None):
        super().__init__(parent)
        self.profile = dict(profile or {})

    def run(self):
        started_at = time.monotonic()
        try:
            provider = LLMFactory.create_provider_from_profile(self.profile)
            preview = provider.test_connection(timeout=20)
            self.finished_signal.emit({
                "ok": True,
                "elapsed": time.monotonic() - started_at,
                "preview": str(preview or "").strip(),
            })
        except Exception as exc:
            self.finished_signal.emit({
                "ok": False,
                "elapsed": time.monotonic() - started_at,
                "error": str(exc),
            })


