class AutoResizingPlainTextEdit(ReadOnlyPlainTextEdit):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self.setFrameStyle(QFrame.NoFrame)
        self.setLineWrapMode(QPlainTextEdit.WidgetWidth)
        self.setWordWrapMode(QTextOption.WrapAtWordBoundaryOrAnywhere)
        text_option = self.document().defaultTextOption()
        text_option.setWrapMode(QTextOption.WrapAtWordBoundaryOrAnywhere)
        self.document().setDefaultTextOption(text_option)
        self.setFixedHeight(24)
        self._height_adjust_pending = False
        self.textChanged.connect(self.scheduleAdjustHeight)
        self.setStyleSheet("background: transparent;")

    def scheduleAdjustHeight(self):
        if not _qt_object_alive(self):
            return
        if self._height_adjust_pending:
            return
        self._height_adjust_pending = True
        QTimer.singleShot(0, self.adjustHeight)

    def adjustHeight(self):
        if not _qt_object_alive(self):
            return
        self._height_adjust_pending = False
        text_option = self.document().defaultTextOption()
        if text_option.wrapMode() != QTextOption.WrapAtWordBoundaryOrAnywhere:
            text_option.setWrapMode(QTextOption.WrapAtWordBoundaryOrAnywhere)
            self.document().setDefaultTextOption(text_option)
        viewport_width = self.viewport().width()
        if viewport_width <= 0:
            viewport_width = self.width() - (self.frameWidth() * 2)
        self.document().setTextWidth(max(0.0, float(viewport_width)))
        line_count = 0
        block = self.document().begin()
        while block.isValid():
            layout = block.layout()
            line_count += max(1, layout.lineCount() if layout is not None else 1)
            block = block.next()
        doc_height = line_count * self.fontMetrics().lineSpacing()
        margins = self.contentsMargins()
        doc_margin = int(self.document().documentMargin() * 2)
        frame = self.frameWidth() * 2
        height = int(doc_height + doc_margin + margins.top() + margins.bottom() + frame + 4)
        height = max(height, 24)
        if self.height() != height:
            self.setFixedHeight(height)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self.adjustHeight()

class AutoResizingInputEdit(QTextEdit):
    returnPressed = Signal()
    mentionRequested = Signal()

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self.setFrameStyle(QFrame.NoFrame)
        self.setLineWrapMode(QTextEdit.WidgetWidth)
        self.setWordWrapMode(QTextOption.WrapAtWordBoundaryOrAnywhere)
        self.textChanged.connect(self.scheduleAdjustHeight)
        self.setFixedHeight(40)
        self.min_height = 40
        self.max_height = 150
        self.anim = None
        self._height_adjust_pending = False
        apply_selection_palette(self)
        QTimer.singleShot(0, self.adjustHeight)

    def canInsertFromMimeData(self, source):
        if source and (source.hasText() or source.hasImage()):
            return True
        return super().canInsertFromMimeData(source)

    def insertFromMimeData(self, source):
        if source and source.hasImage():
            window = self.window()
            if window and hasattr(window, "_add_clipboard_image"):
                window._add_clipboard_image(source.imageData())
                return
        if source and source.hasText():
            self.insertPlainText(source.text())
            return
        super().insertFromMimeData(source)

    def scheduleAdjustHeight(self):
        if not _qt_object_alive(self):
            return
        if self._height_adjust_pending:
            return
        self._height_adjust_pending = True
        QTimer.singleShot(0, self.adjustHeight)

    def adjustHeight(self):
        if not _qt_object_alive(self):
            return
        self._height_adjust_pending = False
        self.document().setTextWidth(max(0.0, float(self.viewport().width())))
        doc_height = self.document().documentLayout().documentSize().height()
        doc_margin = int(self.document().documentMargin() * 2)
        margins = self.contentsMargins()
        viewport_margins = self.viewportMargins()
        frame_width = self.frameWidth() * 2
        height = int(
            doc_height
            + doc_margin
            + margins.top()
            + margins.bottom()
            + viewport_margins.top()
            + viewport_margins.bottom()
            + frame_width
        )
        if height < self.min_height:
            height = self.min_height
        elif height > self.max_height:
            self.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
            height = self.max_height
        else:
            self.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
            height = max(height, self.min_height)
            
        if self.height() != height:
            if self.anim: self.anim.stop()
            self.anim = QVariantAnimation()
            self.anim.setDuration(150)
            self.anim.setStartValue(self.height())
            self.anim.setEndValue(height)
            self.anim.setEasingCurve(QEasingCurve.OutCubic)
            self.anim.valueChanged.connect(lambda v: self.setFixedHeight(int(v)))
            self.anim.start()

    def keyPressEvent(self, event):
        if event.key() == Qt.Key_Return or event.key() == Qt.Key_Enter:
            if event.modifiers() & Qt.ShiftModifier:
                super().keyPressEvent(event)
            else:
                self.returnPressed.emit()
                event.accept()
        elif event.text() == "@":
            super().keyPressEvent(event)
            QTimer.singleShot(0, self.mentionRequested.emit)
        else:
            super().keyPressEvent(event)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self.scheduleAdjustHeight()

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            event.acceptProposedAction()
        else:
            super().dragEnterEvent(event)

    def dropEvent(self, event):
        urls = event.mimeData().urls()
        if urls:
            path = urls[0].toLocalFile()
            if os.path.isdir(path):
                event.ignore() 
                return
            elif os.path.isfile(path):
                window = self.window()
                if window and hasattr(window, "_add_prompt_files"):
                    window._add_prompt_files([path])
                else:
                    self.insertPlainText(path)

            event.acceptProposedAction()
            return
        super().dropEvent(event)
    
    def contextMenuEvent(self, event):
        menu = create_styled_menu(self)
        populate_text_context_menu(menu, self, editable=True)
        menu.exec(event.globalPos())

class DaemonRequestWorker(QThread):
    finished_signal = Signal(object, str)

    def __init__(self, client, session_id, content, workspace_dir=None, run_context=None, messages=None, parent=None):
        super().__init__(parent)
        self.client = client
        self.session_id = session_id
        self.content = content
        self.workspace_dir = workspace_dir
        self.run_context = run_context or {}
        self.messages = copy.deepcopy(messages or [])
        self._aborted = False
        self._sock = None

    def abort(self):
        self._aborted = True

    def run(self):
        try:
            resp = self.client.send_message(
                self.session_id,
                self.content,
                self.workspace_dir,
                run_context=self.run_context,
                messages=self.messages,
            )
        except Exception:
            resp = None
        if self._aborted:
            return
        if not resp or resp.get("status") != "ok":
            error_text = resp.get("error") if isinstance(resp, dict) else "Daemon offline"
            result = {"error": error_text}
        else:
            result = resp.get("result") or {"error": "No response"}
        if self._aborted:
            return
        self.finished_signal.emit(result, self.session_id)


class DaemonStreamWorker(QThread):
    finished_signal = Signal(object, str)
    thinking_signal = Signal(str)
    content_signal = Signal(str)
    tool_call_signal = Signal(dict)
    tool_result_signal = Signal(dict)
    observability_signal = Signal(dict)
    agent_state_signal = Signal(dict)
    output_signal = Signal(str)
    interaction_signal = Signal(dict)
    turn_started_signal = Signal(str)

    def __init__(self, client, session_id, content, workspace_dir=None, run_context=None, messages=None, turn_id=None, parent=None):
        super().__init__(parent)
        self.client = client
        self.session_id = session_id
        self.content = content
        self.workspace_dir = workspace_dir
        self.run_context = run_context or {}
        self.messages = copy.deepcopy(messages or [])
        self.turn_id = str(turn_id or "")
        self._aborted = False
        self._sock = None

    def _abort_remote_session(self):
        log_sub_agent_runtime(
            "daemon_stream_worker_abort_remote",
            session_id=self.session_id,
        )
        try:
            self.client.stop_session(self.session_id)
        except Exception:
            pass

    def abort(self):
        self._aborted = True
        log_sub_agent_runtime(
            "daemon_stream_worker_abort",
            session_id=self.session_id,
        )
        self._abort_remote_session()
        if self._sock:
            try:
                self._sock.shutdown(socket.SHUT_RDWR)
            except Exception:
                pass
            try:
                self._sock.close()
            except Exception:
                pass

    def run(self):
        log_sub_agent_runtime(
            "daemon_stream_worker_run_begin",
            session_id=self.session_id,
            workspace_dir=self.workspace_dir,
            run_context_keys=sorted(list((self.run_context or {}).keys())),
        )
        try:
            with socket.create_connection((self.client.host, self.client.port), timeout=self.client.send_timeout) as sock:
                self._sock = sock
                payload = {
                    "action": "send_message_stream",
                    "session_id": self.session_id,
                    "content": self.content,
                    "workspace_dir": self.workspace_dir,
                    "run_context": self.run_context,
                    "turn_id": self.turn_id,
                }
                if self.messages:
                    payload["messages"] = self.messages
                sock.sendall((json.dumps(payload, ensure_ascii=False) + "\n").encode("utf-8"))
                reader = sock.makefile("r", encoding="utf-8")
                for line in reader:
                    if self._aborted:
                        return
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        msg = json.loads(line)
                    except Exception:
                        continue
                    if msg.get("type") == "thinking":
                        self.thinking_signal.emit(msg.get("delta", ""))
                    elif msg.get("type") == "turn_started":
                        self.turn_started_signal.emit(str(msg.get("turn_id") or ""))
                    elif msg.get("type") == "content":
                        self.content_signal.emit(msg.get("delta", ""))
                    elif msg.get("type") == "tool_call":
                        data = msg.get("data") or {}
                        self.tool_call_signal.emit(data)
                    elif msg.get("type") == "tool_result":
                        data = msg.get("data") or {}
                        self.tool_result_signal.emit(data)
                    elif msg.get("type") == "observability":
                        data = msg.get("data") or {}
                        if isinstance(data, dict):
                            self.observability_signal.emit(data)
                    elif msg.get("type") == "agent_state":
                        data = msg.get("data") or {}
                        if isinstance(data, dict):
                            self.agent_state_signal.emit(data)
                    elif msg.get("type") == "interaction_request":
                        data = msg.get("data") or {}
                        if isinstance(data, dict) and data.get("request_id"):
                            self.interaction_signal.emit(data)
                    elif msg.get("type") == "final":
                        result = msg.get("result") or {"error": "No response"}
                        if isinstance(result, dict):
                            result["_streamed"] = True
                        log_sub_agent_runtime(
                            "daemon_stream_worker_final",
                            session_id=self.session_id,
                            result_keys=sorted(list(result.keys())) if isinstance(result, dict) else [],
                        )
                        self.finished_signal.emit(result, self.session_id)
                        return
                    elif msg.get("type") == "error":
                        result = {"error": msg.get("error") or "Daemon error", "_streamed": True}
                        log_sub_agent_runtime(
                            "daemon_stream_worker_error_message",
                            session_id=self.session_id,
                            error=result.get("error"),
                        )
                        self.finished_signal.emit(result, self.session_id)
                        return
                    elif msg.get("status") == "error":
                        result = {"error": msg.get("error") or "Daemon error", "_streamed": True}
                        log_sub_agent_runtime(
                            "daemon_stream_worker_status_error",
                            session_id=self.session_id,
                            error=result.get("error"),
                        )
                        self.finished_signal.emit(result, self.session_id)
                        return
                    elif msg.get("status") == "ok" and "result" in msg:
                        result = msg.get("result") or {"error": "No response"}
                        if isinstance(result, dict):
                            result["_streamed"] = True
                        log_sub_agent_runtime(
                            "daemon_stream_worker_ok_result",
                            session_id=self.session_id,
                            result_keys=sorted(list(result.keys())) if isinstance(result, dict) else [],
                        )
                        self.finished_signal.emit(result, self.session_id)
                        return
                if not self._aborted:
                    log_sub_agent_runtime(
                        "daemon_stream_worker_reader_eof",
                        session_id=self.session_id,
                    )
                    self.finished_signal.emit({"error": "Daemon stream closed", "_streamed": True}, self.session_id)
        except Exception as e:
            if not self._aborted:
                text = str(e)
                if "timed out" in text.lower() or "timeout" in text.lower():
                    self._abort_remote_session()
                    text = "Confirmation timed out. Conversation interrupted."
                log_sub_agent_runtime(
                    "daemon_stream_worker_exception",
                    session_id=self.session_id,
                    error=text,
                )
                self.finished_signal.emit({"error": text, "_streamed": True}, self.session_id)
        finally:
            log_sub_agent_runtime(
                "daemon_stream_worker_run_end",
                session_id=self.session_id,
                aborted=self._aborted,
            )
            self._sock = None


class DaemonSteerWorker(QThread):
    finished_signal = Signal(dict)

    def __init__(self, client, session_id, expected_turn_id, message, parent=None):
        super().__init__(parent)
        self.client = client
        self.session_id = session_id
        self.expected_turn_id = str(expected_turn_id or "")
        self.message = copy.deepcopy(message or {})

    def run(self):
        response = self.client.steer_message(
            self.session_id,
            self.expected_turn_id,
            self.message,
        )
        if not isinstance(response, dict):
            response = {"status": "error", "accepted": False, "error": "daemon_unavailable"}
        self.finished_signal.emit(response)


class DaemonConnectWorker(QThread):
    finished_signal = Signal(dict)

    def __init__(
        self,
        host,
        port,
        runtime_signature,
        allow_start=False,
        retries=0,
        timeout=UI_DAEMON_CONNECT_TIMEOUT_SEC,
        parent=None,
    ):
        super().__init__(parent)
        self.host = host
        self.port = port
        self.runtime_signature = str(runtime_signature or "").strip()
        self.allow_start = bool(allow_start)
        self.retries = max(0, int(retries or 0))
        self.timeout = timeout

    def _signature_matches(self, payload):
        if not isinstance(payload, dict):
            return False
        remote = str(payload.get("signature") or "").strip()
        return bool(remote and self.runtime_signature and remote == self.runtime_signature)

    def run(self):
        payload = {"connected": False, "process": None}
        client = DaemonClient(self.host, self.port, timeout=self.timeout)
        ping_payload = client.ping()
        connected = bool(ping_payload)
        if connected and not self._signature_matches(ping_payload):
            try:
                client.shutdown()
            except Exception:
                pass
            time.sleep(0.2)
            connected = False
        if not connected and self.allow_start:
            launch_lock = acquire_process_singleton(
                build_process_singleton_lock_path(get_app_data_dir(), f"daemon-launch-{self.port}")
            )
            try:
                if launch_lock:
                    payload["process"] = launch_daemon_subprocess(self.port)
                else:
                    payload["launch_skipped"] = "busy"
            except Exception as exc:
                payload["error"] = str(exc)
            for _ in range(self.retries):
                time.sleep(0.2)
                retry_ping = client.ping()
                if retry_ping and self._signature_matches(retry_ping):
                    connected = True
                    break
        payload["connected"] = connected
        self.finished_signal.emit(payload)


class DaemonStatusWorker(QThread):
    finished_signal = Signal(dict)

    def __init__(
        self,
        host,
        port,
        runtime_signature,
        timeout=UI_DAEMON_CONNECT_TIMEOUT_SEC,
        parent=None,
    ):
        super().__init__(parent)
        self.host = host
        self.port = port
        self.runtime_signature = str(runtime_signature or "").strip()
        self.timeout = timeout

    def _signature_matches(self, payload):
        if not isinstance(payload, dict):
            return False
        remote = str(payload.get("signature") or "").strip()
        return bool(remote and self.runtime_signature and remote == self.runtime_signature)

    def run(self):
        payload = {"connected": False, "status_text": "守护进程未连接"}
        client = DaemonClient(self.host, self.port, timeout=self.timeout)
        ping_payload = client.ping()
        connected = bool(ping_payload)
        if connected and not self._signature_matches(ping_payload):
            try:
                client.shutdown()
            except Exception:
                pass
            time.sleep(0.2)
            connected = False
        if connected:
            status = client.status()
            if status and status.get("status") == "ok":
                state_text = "已休眠" if status.get("suspended") else "运行中"
                sessions = status.get("sessions", 0)
                payload["status_text"] = f"守护进程: {state_text} | 会话缓存: {sessions}"
            else:
                connected = False
        payload["connected"] = connected
        self.finished_signal.emit(payload)

class HistoryTitleButton(QLabel):
    clicked = Signal()

    def __init__(self, title, parent=None):
        super().__init__(parent)
        self._full_title = title or ""
        self._display_title = ""
        self.setMinimumWidth(0)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        self.setToolTip(self._full_title)
        self.setCursor(Qt.PointingHandCursor)
        self.setTextInteractionFlags(Qt.NoTextInteraction)
        self._apply_elide()

    def set_full_title(self, title):
        self._full_title = title or ""
        self.setToolTip(self._full_title)
        self._apply_elide()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._apply_elide()

    def _apply_elide(self):
        metrics = QFontMetrics(self.font())
        available = max(24, self.width())
        display = metrics.elidedText(self._full_title, Qt.ElideRight, available)
        if display != self._display_title:
            self._display_title = display
            self.setText(display)

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.LeftButton:
            self.clicked.emit()
            event.accept()
            return
        super().mouseReleaseEvent(event)


class SidebarHoverTipController(QObject):
    SHOW_DELAY_MS = 350
    MARGIN = 8
    GAP = 6

    def __init__(self, host):
        super().__init__(host)
        self.host = host
        self._texts = {}
        self._pending_widget = None
        self._timer = QTimer(self)
        self._timer.setSingleShot(True)
        self._timer.setInterval(self.SHOW_DELAY_MS)
        self._timer.timeout.connect(self._show_pending)

        self.bubble = QLabel(host)
        self.bubble.setObjectName("SidebarHoverTip")
        self.bubble.setAttribute(Qt.WA_TransparentForMouseEvents)
        self.bubble.setAlignment(Qt.AlignCenter)
        self.bubble.setStyleSheet(
            f"QLabel#SidebarHoverTip {{"
            f"background: {DesignTokens.bg_card};"
            f"color: {DesignTokens.text_primary};"
            f"border: 1px solid {DesignTokens.border_subtle};"
            "border-radius: 7px;"
            "padding: 5px 8px;"
            "font-size: 12px;"
            "font-weight: 500;"
            "}"
        )
        add_soft_shadow(self.bubble, blur=16, y_offset=4, alpha=38)
        self.bubble.hide()

    def register(self, widget, text):
        text = str(text or "").strip()
        if not text:
            raise ValueError("侧边栏按钮提示文案不能为空。")
        self._texts[widget] = text
        widget.setToolTip(text)
        widget.setAccessibleName(text)
        return widget

    def eventFilter(self, obj, event):
        if obj not in self._texts:
            return super().eventFilter(obj, event)
        if event.type() == QEvent.Enter:
            self._pending_widget = obj
            self._timer.start()
        elif event.type() in (QEvent.Leave, QEvent.MouseButtonPress, QEvent.Hide, QEvent.Destroy):
            self.hide()
        return super().eventFilter(obj, event)

    def hide(self):
        self._timer.stop()
        self._pending_widget = None
        self.bubble.hide()

    def _show_pending(self):
        widget = self._pending_widget
        if widget is None or not widget.isVisible() or not widget.underMouse():
            self.hide()
            return
        self.bubble.setText(self._texts[widget])
        self.bubble.adjustSize()

        anchor = widget.mapTo(self.host, QPoint(widget.width(), widget.height() // 2))
        x = anchor.x() + self.GAP
        y = anchor.y() - self.bubble.height() // 2
        if x + self.bubble.width() + self.MARGIN > self.host.width():
            left_anchor = widget.mapTo(self.host, QPoint(0, widget.height() // 2))
            x = left_anchor.x() - self.bubble.width() - self.GAP
        x = max(self.MARGIN, min(x, self.host.width() - self.bubble.width() - self.MARGIN))
        y = max(self.MARGIN, min(y, self.host.height() - self.bubble.height() - self.MARGIN))
        self.bubble.move(x, y)
        self.bubble.raise_()
        self.bubble.show()


class ConversationHistoryRow(QFrame):
    def __init__(self, parent=None):
        super().__init__(parent)
        self._hover_actions = []
        self._hover_hidden = []

    def set_hover_actions(self, widgets, hide_widgets=None):
        self._hover_actions = list(widgets or [])
        self._hover_hidden = list(hide_widgets or [])
        self._set_actions_visible(False)

    def _set_actions_visible(self, visible):
        for widget in self._hover_actions:
            widget.setVisible(bool(visible))
        for widget in self._hover_hidden:
            widget.setVisible(not bool(visible))

    def enterEvent(self, event):
        self._set_actions_visible(True)
        super().enterEvent(event)

    def leaveEvent(self, event):
        self._set_actions_visible(False)
        super().leaveEvent(event)

    def focusInEvent(self, event):
        self._set_actions_visible(True)
        super().focusInEvent(event)

    def focusOutEvent(self, event):
        focused = QApplication.focusWidget()
        if not (focused and self.isAncestorOf(focused)):
            self._set_actions_visible(False)
        super().focusOutEvent(event)


class ProjectHistoryRow(ConversationHistoryRow):
    activated = Signal()

    def keyPressEvent(self, event):
        if event.key() in {Qt.Key_Return, Qt.Key_Enter, Qt.Key_Space}:
            self.activated.emit()
            event.accept()
            return
        super().keyPressEvent(event)


