class SessionActivityIndicator(QWidget):
    """Small, quiet activity ring used by live conversations in the sidebar."""

    def __init__(self, parent=None, size=None):
        super().__init__(parent)
        self._angle = 90
        self._running = False
        self._state = "idle"
        self._timer = QTimer(self)
        self._timer.setInterval(DesignTokens.activity_indicator_interval_ms)
        self._timer.timeout.connect(self._advance)
        size = int(size or DesignTokens.activity_indicator_size)
        self.setFixedSize(size, size)
        self.setToolTip("运行中")
        self.setAccessibleName("运行中")
        self.setVisible(False)

    def setRunning(self, running):
        self.setState("running" if running else "idle")

    def setState(self, state):
        state = str(state or "idle")
        running = state == "running"
        if self._state == state and self._running == running:
            return
        self._state = state
        self._running = running
        self.setVisible(state != "idle")
        labels = {"running": "运行中", "waiting": "等待输入", "error": "失败"}
        label = labels.get(state, "")
        self.setToolTip(label)
        self.setAccessibleName(label)
        if running and self.isVisible():
            self._timer.start()
        else:
            self._timer.stop()
        self.update()

    def showEvent(self, event):
        super().showEvent(event)
        if self._running:
            self._timer.start()

    def hideEvent(self, event):
        self._timer.stop()
        super().hideEvent(event)

    def _advance(self):
        self._angle = (self._angle - 24) % 360
        self.update()

    def paintEvent(self, event):
        if self._state == "idle":
            return
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)
        rect = self.rect().adjusted(2, 2, -2, -2)

        if self._state in {"waiting", "error"}:
            color = DesignTokens.warning_text if self._state == "waiting" else DesignTokens.error_text
            painter.setPen(Qt.NoPen)
            painter.setBrush(QColor(color))
            painter.drawEllipse(rect.adjusted(2, 2, -2, -2))
            return

        track = QColor(DesignTokens.border_strong)
        track.setAlpha(110)
        track_pen = QPen(track)
        track_pen.setWidthF(DesignTokens.activity_indicator_stroke)
        painter.setPen(track_pen)
        painter.drawEllipse(rect)

        active_pen = QPen(QColor(DesignTokens.primary))
        active_pen.setWidthF(DesignTokens.activity_indicator_stroke)
        active_pen.setCapStyle(Qt.RoundCap)
        painter.setPen(active_pen)
        painter.drawArc(rect, self._angle * 16, 104 * 16)


